@section('scripts')
    <script>
        document.addEventListener('DOMContentLoaded', function () {
            const nameInput = document.getElementById('sim-name');
            const amountFormattedInput = document.getElementById('sim-amount-formatted');
            const amountHiddenInput = document.getElementById('sim-amount');
            const monthsInput = document.getElementById('sim-months');
            const monthsVal = document.getElementById('sim-months-val');

            const displayName = document.getElementById('display-sim-name');
            const calcDaily = document.getElementById('calc-daily');
            const calcMonthly = document.getElementById('calc-monthly');
            const calcTotal = document.getElementById('calc-total');

            function formatRupiah(val) {
                if (isNaN(val) || val === null || val === undefined) val = 0;
                return 'Rp ' + new Intl.NumberFormat('id-ID').format(Math.round(val));
            }

            function updateCalculator() {
                if (!nameInput || !amountHiddenInput || !monthsInput || !displayName || !calcDaily || !calcMonthly || !calcTotal || !monthsVal) {
                    return;
                }

                const name = nameInput.value.trim() || 'Impian Saya';
                const amount = parseFloat(amountHiddenInput.value) || 0;
                const months = parseInt(monthsInput.value, 10) || 1;

                const currentLang = localStorage.getItem('lang') || 'id';
                const suffix = currentLang === 'en' ? ' Months' : ' Bulan';
                monthsVal.textContent = months + suffix;
                displayName.textContent = name;

                const days = months * 30;
                const dailyAmount = amount > 0 ? amount / days : 0;
                const monthlyAmount = amount > 0 ? amount / months : 0;

                const dailySuffix = currentLang === 'en' ? ' / day' : ' / hari';
                calcDaily.innerHTML = formatRupiah(dailyAmount) + ' <span class="text-xs text-slate-400 font-normal">' + dailySuffix + '</span>';
                calcMonthly.textContent = formatRupiah(monthlyAmount);
                calcTotal.textContent = formatRupiah(amount);
            }

            if (amountFormattedInput && amountHiddenInput) {
                amountFormattedInput.addEventListener('input', function () {
                    let rawValue = this.value.replace(/[^0-9]/g, '');
                    if (!rawValue) rawValue = '0';

                    const numericValue = parseInt(rawValue, 10);
                    amountHiddenInput.value = numericValue;
                    this.value = formatRupiah(numericValue);

                    updateCalculator();
                });
            }

            if (nameInput) nameInput.addEventListener('input', updateCalculator);
            if (monthsInput) monthsInput.addEventListener('input', updateCalculator);

            updateCalculator();
        });
    </script>
@endsection
